//! strtok, strspn, strcspn, strpbrk, strstr — tokens, spans, and search offsets.

c_run_cases! {
    strtok_splits_colon_delimited => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"one:two:three\";", body: "char *tok=strtok(s, \":\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \":\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \":\"); printf(\"%s\\n\", tok); return 0;", expect: ["one", "two", "three"] },
    strtok_single_token_no_delim => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"solo\";", body: "printf(\"%s\\n\", strtok(s, \",\")); return 0;", expect: ["solo"] },
    strtok_leading_delimiter_skipped => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \",a,b\";", body: "char *tok=strtok(s, \",\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \",\"); printf(\"%s\\n\", tok); return 0;", expect: ["a", "b"] },
    strtok_trailing_delimiter_ignored => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"x,y,\";", body: "char *tok=strtok(s, \",\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \",\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \",\"); printf(\"%d\\n\", tok==NULL); return 0;", expect: ["x", "y", "1"] },
    strtok_multi_char_delim_set => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"a|b;c\";", body: "char *tok=strtok(s, \"|;\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \"|;\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \"|;\"); printf(\"%s\\n\", tok); return 0;", expect: ["a", "b", "c"] },
    strtok_space_tab_delimiters => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"alpha beta\";", body: "char *tok=strtok(s, \" \\t\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \" \\t\"); printf(\"%s\\n\", tok); return 0;", expect: ["alpha", "beta"] },
    strtok_empty_string_returns_null => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"\";", body: "printf(\"%d\\n\", strtok(s, \",\")==NULL); return 0;", expect: ["1"] },
    strtok_modifies_buffer_in_place => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"p:q\";", body: "strtok(s, \":\"); printf(\"%d\\n\", s[1]=='\\0'); return 0;", expect: ["1"] },
    strtok_digit_tokens => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"10-20-30\";", body: "char *tok=strtok(s, \"-\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \"-\"); printf(\"%s\\n\", tok); return 0;", expect: ["10", "20"] },
    strtok_repeated_delim_collapsed => { includes: ["<stdio.h>", "<string.h>"], decls: "char s[] = \"a,,b\";", body: "char *tok=strtok(s, \",\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \",\"); printf(\"%s\\n\", tok); tok=strtok(NULL, \",\"); printf(\"%s\\n\", tok); return 0;", expect: ["a", "", "b"] },
    strspn_digits_prefix => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"123abc\", \"0123456789\")); return 0;", expect: ["3"] },
    strspn_letters_prefix => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"hello123\", \"abcdefghijklmnopqrstuvwxyz\")); return 0;", expect: ["5"] },
    strspn_empty_accept_set => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"anything\", \"\")); return 0;", expect: ["0"] },
    strspn_full_match => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"zzz\", \"xyz\")); return 0;", expect: ["3"] },
    strspn_no_match => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"@abc\", \"abc\")); return 0;", expect: ["0"] },
    strspn_space_run => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"   tab\", \" \")); return 0;", expect: ["3"] },
    strspn_hex_prefix => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"0xFF00\", \"0123456789ABCDEFabcdefx\")); return 0;", expect: ["6"] },
    strspn_mixed_case_letters => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"AbCd9\", \"ABcd\")); return 0;", expect: ["4"] },
    strspn_single_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"x\", \"x\")); return 0;", expect: ["1"] },
    strspn_stop_at_first_mismatch => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strspn(\"aabacc\", \"ab\")); return 0;", expect: ["3"] },
    strcspn_until_space => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"hello world\", \" \")); return 0;", expect: ["5"] },
    strcspn_until_comma => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"field,value\", \",\")); return 0;", expect: ["5"] },
    strcspn_no_stop_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"nodivide\", \"|\")); return 0;", expect: ["8"] },
    strcspn_immediate_stop => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"!start\", \"!\")); return 0;", expect: ["0"] },
    strcspn_newline_break => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"line\\nrest\", \"\\n\")); return 0;", expect: ["4"] },
    strcspn_tab_break => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"col\\tdata\", \"\\t\")); return 0;", expect: ["3"] },
    strcspn_multi_reject_set => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"abc123\", \"0123456789\")); return 0;", expect: ["3"] },
    strcspn_empty_reject_set => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"whole\", \"\")); return 0;", expect: ["5"] },
    strcspn_digit_then_letter => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"99a\", \"a\")); return 0;", expect: ["2"] },
    strcspn_punctuation_stop => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", (int)strcspn(\"word.\", \".\")); return 0;", expect: ["4"] },
    strpbrk_no_vowel_returns_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strpbrk(\"rhythm\", \"aeiou\")==NULL); return 0;", expect: ["1"] },
    strpbrk_finds_earliest_in_set => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"xyzabc\", \"cba\")); return 0;", expect: ["cabc"] },
    strpbrk_digit_in_string => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"no7here\", \"0123456789\")); return 0;", expect: ["7here"] },
    strpbrk_no_match_returns_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strpbrk(\"nowrap\", \" \")==NULL); return 0;", expect: ["1"] },
    strpbrk_punctuation_hit => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"plain!\", \"!?.\")); return 0;", expect: ["!"] },
    strpbrk_at_start => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"@mail\", \"@\")); return 0;", expect: ["@mail"] },
    strpbrk_multi_set_first_occurrence => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%c\\n\", *strpbrk(\"ab#cd\", \"#*\")); return 0;", expect: ["#"] },
    strpbrk_returns_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"find_me\", \"_\")); return 0;", expect: ["_me"] },
    strpbrk_uppercase_letter => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strpbrk(\"lowerUP\", \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\")); return 0;", expect: ["UP"] },
    strpbrk_empty_search_set => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strpbrk(\"text\", \"\")==NULL); return 0;", expect: ["1"] },
    strstr_suffix_printed => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"foobar\", \"bar\")); return 0;", expect: ["bar"] },
    strstr_not_found_flag => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strstr(\"needle\", \"hay\")==NULL); return 0;", expect: ["1"] },
    strstr_offset_from_start => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[] = \"abcdef\";", body: "printf(\"%d\\n\", (int)(strstr(h, \"de\") - h)); return 0;", expect: ["3"] },
    strstr_single_char_needle => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"queue\", \"u\")); return 0;", expect: ["ueue"] },
    strstr_needle_longer_than_haystack => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strstr(\"ab\", \"abcd\")==NULL); return 0;", expect: ["1"] },
    strstr_repeated_pattern => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"aaaa\", \"aaa\")); return 0;", expect: ["aaaa"] },
    strstr_at_end => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"prefix_end\", \"end\")); return 0;", expect: ["end"] },
    strstr_case_sensitive_miss => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strstr(\"Case\", \"case\")==NULL); return 0;", expect: ["1"] },
    strstr_empty_needle_returns_haystack => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"data\", \"\")); return 0;", expect: ["data"] },
    strstr_overlapping_candidate => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", strstr(\"abcabc\", \"bcab\")); return 0;", expect: ["bcabc"] },
}
